CREATE TABLE finance_transaction (id UUID PRIMARY KEY DEFAULT uuid_v7(),ledger_id UUID NOT NULL,owner_id UUID NOT NULL,type VARCHAR(24) NOT NULL,account_id UUID NOT NULL,target_account_id UUID,amount NUMERIC(19,4) NOT NULL,currency CHAR(3) NOT NULL,category_id UUID,payee VARCHAR(256),note TEXT,occurred_at TIMESTAMPTZ NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'POSTED',source VARCHAR(64),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(type IN ('INCOME','EXPENSE','TRANSFER','ADJUSTMENT')),CHECK(status IN ('POSTED','VOIDED')),CHECK(amount>0),CHECK(type<>'TRANSFER' OR target_account_id IS NOT NULL),FOREIGN KEY(ledger_id) REFERENCES finance_ledger(id),FOREIGN KEY(account_id) REFERENCES finance_account(id),FOREIGN KEY(target_account_id) REFERENCES finance_account(id)); CREATE INDEX idx_finance_transaction_time ON finance_transaction(ledger_id,occurred_at DESC);
